10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.web.bind.annotation.PathVariable;
12	import org.springframework.web.bind.annotation.RequestParam;
13	
14	public class BuildClaim {
15	    public void build(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
16	            @Val ClaimInput input, Claims claims, Periods periods, Settings settings, Holidays holidays, ClaimLog log, Audit audit, Rollup rollup)
17	            throws InvalidClaimException {
18	        // The due-by is fixed now, from the terms of the person's grade in force on the claim's date, as they
19	        // stand on that date; the claim belongs to the period its due-by falls in.
20	        LocalDate dueBy = person.dueBy(sheet, input.date(), settings, holidays);
21	        if (periods.closedOn(sheet, dueBy)) {
22	            throw new InvalidClaimException("A claim may not be due inside a closed period");
23	        }
24	        if (person.retiredBefore(input.date())) {
25	            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
26	        }
27	        input.checkCorrects(sheet, person.id(), claims);
28	        Rollup.Snapshot before = rollup.take(sheet);
29	        long id = claims.add(sheet, person.id(), input, dueBy);
30	        log.record(sheet, user, id);
31	        audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
32	        if (periods.softClosedOn(sheet, dueBy)) {
33	            claims.setLateEntry(sheet, id);
34	            audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
35	        }
36	        rollup.record(sheet, user, before);
37	    }
38	}
