48	/**
49	 * A claim as the screen shows it: amount with two decimals, date (ISO yyyy-MM-dd), note, status and its number on
50	 * the sheet (given when opened and kept once voided; null while a draft), and its due fixed when settled (two decimals;
51	 * null until settled, and when the grade had no rate then), and the user who opened it (null until opened), and
52	 * whether its person's last statement bound it, with the figure it bound (null when the grade had no rate then), and
53	 * the number of the claim it corrects (null unless it is a correction), and the date it rounds on: its own, or for
54	 * a correction the date of the claim it corrects, and its number within its period (<period>-<n>, or X-<n> in no
55	 * period) when it was opened while the sheet numbered by period, in place of a number on the sheet (null otherwise),
56	 * and its due-by (yyyy-MM-dd), fixed when it was added from the terms of its person's grade in force on its date,
57	 * and its status log, oldest first, and the date it was last deferred until (null when never), with whether it is
58	 * deferred now: OPEN with that date after the sheet's today, and its proofs count, and the number (as it shows) of
59	 * the claim it was split off (null unless it was), and the user whose open editor locks it (null when none does),
60	 * and whether it was added while its period was soft-closed (a late entry), and the sheet's today it was last
61	 * reminded on (null when never).
62	 */
63	public record Claim(long id, long person, String amount, String date, String note, ClaimStatus status,
64	        Integer number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
65	        String roundsOn, String periodNumber, String dueBy, List<ClaimLogLine> log, String deferredUntil, boolean deferred, int proofs,
66	        String splitFrom, String lockedBy, boolean lateEntry, String remindedOn) {
67	
68	    /** Whether this claim is a correction: a negative amount, naming the number (as it shows) of the settled claim it corrects. */
69	    public boolean correction() {
70	        return amount.startsWith("-");
71	    }
72	
73	    /** The audit fields of this claim for the named person, as {@link ClaimInput#auditFields}. */
74	    public String auditFields(String person) {
75	        return "person=" + person + " amount=" + amount + " date=" + date;
76	    }
77	
78	    /** This claim, numbered: its audit fields end with number=<number> when it has one. */
79	    public Claim withNumber(Integer number) {
80	        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
81	    }
82	
83	    /** This claim, numbered within its period: its audit fields end with number=<period number>. */
84	    public Claim withPeriodNumber(String periodNumber) {
85	        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
86	    }
87	
88	    /** This claim with another date (yyyy-MM-dd), as once re-dated. */
89	    public Claim withDate(String date) {
90	        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
91	    }
92	
93	    /** This claim with another amount (two decimals), as its remaining amount once split. */
94	    public Claim withAmount(String amount) {
95	        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
96	    }
97	
98	    /** This claim, settled with its due fixed (null when its grade had no rate). */
99	    public Claim withSettledDue(String settledDue) {
100	        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
101	    }
102	
103	    /** This claim as an OPEN claim bound by no statement and with no due fixed: the figure it would have live. */
104	    public Claim asOpenUnbound() {
105	        return new Claim(id, person, amount, date, note, ClaimStatus.OPEN, number, null, openedBy, false, null, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
106	    }
107	
108	    /** This claim as it stands with the date for the sheet's today: deferred while OPEN with its deferred-until after it. */
109	    public Claim on(LocalDate today) {
110	        boolean deferredThen = status == ClaimStatus.OPEN && deferredUntil != null && LocalDate.parse(deferredUntil).isAfter(today);
111	        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferredThen, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
112	    }
113	
114	    /** This claim, with its status log (oldest first). */
115	    public Claim withLog(List<ClaimLogLine> log) {
116	        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn);
117	    }
118	
119	    /** The date it was last settled: its status log's last SETTLED line (null when the log has none). */
120	    public LocalDate settledOn() {
121	        LocalDate on = null;
122	        for (ClaimLogLine line : log == null ? List.<ClaimLogLine>of() : log) {
123	            if (line.status() == ClaimStatus.SETTLED) {
124	                on = LocalDate.parse(line.on());
125	            }
126	        }
127	        return on;
128	    }
129	
130	    /** The number the claim shows: its number within its period, else its number on the sheet; null for none. */
131	    public String shownNumber() {
132	        return periodNumber != null ? periodNumber : number == null ? null : number.toString();
133	    }
134	
135	    /** The audit fields of a status change: {@link #auditFields} then number=<number> when it has one. */
136	    public String statusAuditFields(String person) {
137	        String shown = shownNumber();
138	        return auditFields(person) + (shown == null ? "" : " number=" + shown);
139	    }
140	
141	    /** Whether this claim counts toward the totals: OPEN, PENDING and SETTLED claims do, unless deferred. */
142	    public boolean counts() {
143	        return !deferred && (status == ClaimStatus.OPEN || status == ClaimStatus.PENDING || status == ClaimStatus.SETTLED);
144	    }
145	
146	    /**
147	     * The status this claim had at the end of the day, as its status log records it (the last line on or before it);
148	     * null when it was not yet added then. A claim kept from before the log (no lines) has its status now.
149	     */
150	    public ClaimStatus statusOn(LocalDate end) {
151	        if (log == null || log.isEmpty()) {
152	            return status;
153	        }
154	        ClaimStatus then = null;
155	        for (ClaimLogLine line : log) {
156	            if (!LocalDate.parse(line.on()).isAfter(end)) {
157	                then = line.status();
158	            }
159	        }
160	        return then;
161	    }
162	
163	    /** Whether this claim's statement binds its figure: it is stated, and not PENDING (which shows its live figure). */
164	    public boolean bound() {
165	        return stated && status != ClaimStatus.PENDING;
166	    }
167	
168	    /**
169	     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
170	     * settled or bound when its grade had no rate keeps none; a PENDING claim is not bound).
171	     */
172	    public boolean fixed() {
173	        return settledDue != null || (bound() && statedDue != null);
174	    }
175	
176	    /**
177	     * This claim's due: the due fixed when settled; else the greater of the sheet's floor in force on its date and its
178	     * {@link #figure} plus, while it is overdue, its late charge on that figure (a correction has no floor and no
179	     * charge); null when there is no figure.
180	     */
181	    public BigDecimal due(List<Rate> rates, String grade, Dated floor, Late late) {
182	        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
183	        if (figure == null || settledDue != null || correction()) {
184	            return figure;
185	        }
186	        return figure.add(late.charge(this, grade, figure)).max(floor.on(date));
187	    }
188	
189	    /**
190	     * This claim's figure: the due fixed when settled, else the rate figure its statement bound (unless PENDING), else
191	     * its amount at the grade's rate in force on its date (the floor is applied last, in {@link #due}); null when
192	     * there is none.
193	     */
194	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor) {
195	        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
196	    }
197	
198	    /** This claim's {@link #figure}, its live figure rounded by the mode. */
199	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor, RoundingMode rounding) {
200	        if (settledDue != null) {
201	            return new BigDecimal(settledDue);
202	        }
203	        if (bound()) {
204	            return statedDue == null ? null : new BigDecimal(statedDue);
205	        }
206	        return Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)), rounding);
207	    }
208	}
