225	/** The claims kept per sheet, each belonging to a person on that sheet. */
226	@Repository
227	public class Claims {
228	
229	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person"),
230	            rs.getBigDecimal("amount").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
231	            rs.getDate("claimed_on").toLocalDate().toString(), rs.getString("note"),
232	            ClaimStatus.valueOf(rs.getString("status")), rs.getObject("number_on_sheet", Integer.class),
233	            rs.getBigDecimal("settled_due") == null ? null
234	                    : rs.getBigDecimal("settled_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
235	            rs.getString("opened_by"), rs.getBoolean("stated"),
236	            rs.getBigDecimal("stated_due") == null ? null
237	                    : rs.getBigDecimal("stated_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
238	            rs.getString("corrects"), rs.getDate("rounds_on").toLocalDate().toString(),
239	            rs.getString("period_number"), rs.getDate("due_by").toLocalDate().toString(), List.of(),
240	            rs.getDate("deferred_until") == null ? null : rs.getDate("deferred_until").toLocalDate().toString(),
241	            rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"),
242	            rs.getString("locked_by"), rs.getBoolean("late_entry"),
243	            rs.getDate("reminded_on") == null ? null : rs.getDate("reminded_on").toLocalDate().toString());
244	
245	    // A claim rounds on its own date; a correction on the date of the claim it corrects (its own when none has it).
246	    // It is deferred while OPEN with its deferred-until after the sheet's today (the real date until one is set).
247	    private static final String COLUMNS = "SELECT claim.id, claim.person, claim.amount, claim.claimed_on, claim.note, claim.status,"
248	            + " claim.number_on_sheet, claim.settled_due, claim.opened_by, claim.stated, claim.stated_due, claim.corrects,"
249	            + " claim.period_number, claim.due_by, COALESCE(corrected.claimed_on, claim.claimed_on) AS rounds_on,"
250	            + " claim.deferred_until, claim.proofs, claim.split_from, claim.locked_by, claim.late_entry, claim.reminded_on, (claim.status = 'OPEN' AND claim.deferred_until IS NOT NULL AND claim.deferred_until >"
251	            + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE)) AS deferred FROM claim"
252	            + " LEFT JOIN claim corrected ON corrected.sheet = claim.sheet AND "
253	            + " COALESCE(corrected.period_number, CAST(corrected.number_on_sheet AS VARCHAR)) = claim.corrects";
254	
255	    // The place after every claim listed on the sheet (bound to the sheet), so the claim lists newest.
256	    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?)";
257	
258	    private final JdbcTemplate jdbc;
259	
260	    public Claims(JdbcTemplate jdbc) {
261	        this.jdbc = jdbc;
262	    }
263	
264	    private static final String LOG = "SELECT claim, status, by_user, on_date, due FROM claim_log WHERE sheet = ?";
265	
266	    /** Every claim on the sheet, newest first. */
267	    public List<Claim> list(String sheet) {
268	        return withLogs(sheet, jdbc.query(COLUMNS + " WHERE claim.sheet = ? ORDER BY claim.listed DESC, claim.id DESC", ROW, sheet),
269	                jdbc.query(LOG + " ORDER BY id", LOG_ROW, sheet));
270	    }
271	
272	    public Claim find(String sheet, long id) {
273	        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ? AND claim.id = ?", ROW, sheet, id);
274	        return found.isEmpty() ? null
275	                : withLogs(sheet, found, jdbc.query(LOG + " AND claim = ? ORDER BY id", LOG_ROW, sheet, id)).get(0);
276	    }
277	
278	    private record Logged(long claim, ClaimLogLine line) {
279	    }
280	
281	    private static final RowMapper<Logged> LOG_ROW = (rs, i) -> new Logged(rs.getLong("claim"),
282	            new ClaimLogLine(ClaimStatus.valueOf(rs.getString("status")), rs.getString("by_user"),
283	                    rs.getDate("on_date").toLocalDate().toString(), rs.getString("due")));
284	
285	    /** The claims, each with its own lines of the status log (oldest first). */
286	    private static List<Claim> withLogs(String sheet, List<Claim> found, List<Logged> logged) {
287	        Map<Long, List<ClaimLogLine>> lines = new HashMap<>();
288	        for (Logged l : logged) {
289	            lines.computeIfAbsent(l.claim(), k -> new ArrayList<>()).add(l.line());
290	        }
291	        return found.stream().map(c -> c.withLog(lines.getOrDefault(c.id(), List.of()))).toList();
292	    }
293	
294	    /** The claim showing this number on the sheet (within its period, or on the sheet), or null when none does. */
295	    public Claim findByNumber(String sheet, String number) {
296	        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ?"
297	                + " AND COALESCE(claim.period_number, CAST(claim.number_on_sheet AS VARCHAR)) = ?", ROW, sheet, number);
298	        return found.isEmpty() ? null : found.get(0);
299	    }
