301	    /** Adds the claim with its due-by, fixed now and never moved after; returns its id. */
302	    public long add(String sheet, long person, ClaimInput input, LocalDate dueBy) {
303	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
304	        jdbc.update(con -> {
305	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects, due_by, listed)"
306	                    + " VALUES (?, ?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", new String[] { "id" });
307	            ps.setString(1, sheet);
308	            ps.setLong(2, person);
309	            ps.setBigDecimal(3, input.amount());
310	            ps.setDate(4, Date.valueOf(input.date()));
311	            ps.setString(5, input.note());
312	            ps.setString(6, input.corrects());
313	            ps.setDate(7, Date.valueOf(dueBy));
314	            ps.setString(8, sheet);
315	            return ps;
316	        }, keys);
317	        return keys.getKey().longValue();
318	    }
319	
320	    /** Marks the claim a late entry: added while the period its due-by falls in was soft-closed. */
321	    public void setLateEntry(String sheet, long id) {
322	        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet = ? AND id = ?", sheet, id);
323	    }
