325	    /**
326	     * Adds the OPEN claim split off another: the amount, with the date and note of the claim it was split from (by
327	     * the number that claim shows), opened by the user, with its due-by fixed now; returns its id.
328	     */
329	    public long addSplit(String sheet, long person, BigDecimal amount, LocalDate date, String note, LocalDate dueBy,
330	            String splitFrom, String openedBy) {
331	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
332	        jdbc.update(con -> {
333	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, due_by, status,"
334	                    + " split_from, opened_by, listed) VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, " + NEXT_LISTED + ")",
335	                    new String[] { "id" });
336	            ps.setString(1, sheet);
337	            ps.setLong(2, person);
338	            ps.setBigDecimal(3, amount);
339	            ps.setDate(4, Date.valueOf(date));
340	            ps.setString(5, note);
341	            ps.setDate(6, Date.valueOf(dueBy));
342	            ps.setString(7, splitFrom);
343	            ps.setString(8, openedBy);
344	            ps.setString(9, sheet);
345	            return ps;
346	        }, keys);
347	        return keys.getKey().longValue();
348	    }
