350	    /**
351	     * Leaves an OPEN claim the rest of its amount once split, unbound from any statement; conditional on the
352	     * amount read and on it still being OPEN and not deferred: false when it no longer is.
353	     */
354	    public boolean split(String sheet, long id, BigDecimal was, BigDecimal rest) {
355	        return jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL WHERE sheet = ? AND id = ?"
356	                + " AND status = 'OPEN' AND amount = ? AND (deferred_until IS NULL OR deferred_until <="
357	                + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE))",
358	                rest, sheet, id, was) == 1;
359	    }
360	
361	    /**
362	     * Edits a draft claim not locked by another user's editor, releasing any lock on it: false when it is no longer a
363	     * draft, or another user's editor holds it.
364	     */
365	    public boolean update(String sheet, long id, ClaimInput input, String user) {
366	        return jdbc.update(
367	                "UPDATE claim SET amount = ?, claimed_on = ?, note = ?, corrects = ?, locked_by = NULL WHERE sheet = ? AND id = ?"
368	                        + " AND status = 'DRAFT' AND (locked_by IS NULL OR locked_by = ?)",
369	                input.amount(), Date.valueOf(input.date()), input.note(), input.corrects(), sheet, id, user) == 1;
370	    }
371	
372	    /**
373	     * Locks a draft claim for the user's editor, releasing any other claim the user's editor held on the sheet:
374	     * false when it is no longer a draft, or another user's editor holds it.
375	     */
376	    public boolean lock(String sheet, long id, String user) {
377	        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'"
378	                + " AND (locked_by IS NULL OR locked_by = ?)", user, sheet, id, user) != 1) {
379	            return false;
380	        }
381	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id <> ? AND locked_by = ?", sheet, id, user);
382	        return true;
383	    }
384	
385	    /** Releases the claim's lock when the user's editor holds it. */
386	    public void unlock(String sheet, long id, String user) {
387	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id = ? AND locked_by = ?", sheet, id, user);
388	    }
389	
390	    /** Releases every lock on the sheet's claims, as when its today changes. */
391	    public void unlockAll(String sheet) {
392	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND locked_by IS NOT NULL", sheet);
393	    }
394	
395	    /**
396	     * Moves the claim of the person and status it was read with to another person, unbound from any statement and
397	     * listed as the sheet's newest: false when it no longer has that person or status.
398	     */
399	    public boolean reassign(String sheet, long id, long from, ClaimStatus status, long to) {
400	        return jdbc.update("UPDATE claim SET person = ?, stated = FALSE, stated_due = NULL, listed = " + NEXT_LISTED
401	                + " WHERE sheet = ? AND id = ? AND person = ? AND status = ?", to, sheet, sheet, id, from,
402	                status.name()) == 1;
403	    }
404	
405	    /**
406	     * Moves the claim of the status and date it was read with to another date, keeping its due-by and any figure its
407	     * statement bound: false when it no longer has that status or date.
408	     */
409	    public boolean redate(String sheet, long id, ClaimStatus status, LocalDate was, LocalDate date) {
410	        return jdbc.update("UPDATE claim SET claimed_on = ? WHERE sheet = ? AND id = ? AND status = ? AND claimed_on = ?",
411	                Date.valueOf(date), sheet, id, status.name(), Date.valueOf(was)) == 1;
412	    }
413	
414	    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
415	    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
416	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
417	                id, from.name()) == 1;
418	    }
419	
420	    /** Defers an OPEN claim until the date: false when it is no longer OPEN. */
421	    public boolean defer(String sheet, long id, LocalDate until) {
422	        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet = ? AND id = ? AND status = 'OPEN'",
423	                Date.valueOf(until), sheet, id) == 1;
424	    }
425	
426	    /**
427	     * Reminds an OPEN or PENDING claim on the date (the sheet's today), conditional on its status read and on it not
428	     * yet being reminded that day: false when it was not.
429	     */
430	    public boolean remind(String sheet, long id, ClaimStatus status, LocalDate today) {
431	        return jdbc.update("UPDATE claim SET reminded_on = ? WHERE sheet = ? AND id = ? AND status = ?"
432	                + " AND (reminded_on IS NULL OR reminded_on <> ?)", Date.valueOf(today), sheet, id, status.name(),
433	                Date.valueOf(today)) == 1;
434	    }
