436	    /**
437	     * Raises the claim's proofs count by one, conditional on the status and count read, so a concurrent change by
438	     * another user is refused, not overwritten: false when it was not.
439	     */
440	    public boolean addProof(String sheet, long id, ClaimStatus status, int was) {
441	        return jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet = ? AND id = ? AND status = ? AND proofs = ?",
442	                sheet, id, status.name(), was) == 1;
443	    }
