445	    /** Fixes the claim's due as it is settled, or leaves none with null. */
446	    public void setSettledDue(String sheet, long id, BigDecimal due) {
447	        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
448	    }
