610	/**
611	 * Checks every pasted line (name,amount,date,note; the note may hold commas, the date may be blank for the sheet's entry
612	 * date or today, the note may be absent) by the claim form's rules before anything is written, so a refused paste adds
613	 * nothing. The name must be on the sheet (ignoring case). A paste carries no corrected number, so a negative amount
614	 * is refused as on the form without one. Blank lines are skipped; a paste with no line is refused.
615	 */
616	public class ValidatePaste {
617	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
618	
619	    public void validate(@PathVariable("sheet") String sheet, @RequestBody PasteRequest request, People people,
620	            Settings settings, Holidays holidays, Periods periods, Out<PastedClaims> pasted) throws InvalidClaimException {
621	        String text = request == null || request.text() == null ? "" : request.text();
622	        List<PastedClaim> lines = new ArrayList<>();
623	        int at = 0;
624	        for (String line : text.split("\\r?\\n")) {
625	            at++;
626	            if (line.isBlank()) {
627	                continue;
628	            }
629	            lines.add(check(sheet, at, line, people, settings, holidays, periods));
630	        }
631	        if (lines.isEmpty()) {
632	            throw new InvalidClaimException("Paste at least one line of name,amount,date,note");
633	        }
634	        pasted.set(new PastedClaims(lines));
635	    }
636	
637	    private static PastedClaim check(String sheet, int at, String line, People people, Settings settings, Holidays holidays,
638	            Periods periods) throws InvalidClaimException {
639	        String[] fields = line.split(",", 4);
640	        String name = fields[0].trim();
641	        String amount = fields.length > 1 ? fields[1].trim() : "";
642	        String date = fields.length > 2 ? fields[2].trim() : "";
643	        String note = fields.length > 3 ? fields[3].trim() : "";
644	        Person person = name.isEmpty() ? null : people.findByName(sheet, name);
645	        if (person == null) {
646	            throw new InvalidClaimException("Line " + at + ": no one named " + name + " is on the sheet");
647	        }
648	        if (!AMOUNT.matcher(amount).matches()) {
649	            throw new InvalidClaimException("Line " + at + ": the amount must be a number with up to two decimals");
650	        }
651	        BigDecimal value = new BigDecimal(amount);
652	        if (value.signum() < 0) {
653	            throw new InvalidClaimException("Line " + at + ": a negative amount must name the claim it corrects");
654	        }
655	        LocalDate on;
656	        try {
657	            on = date.isEmpty() ? settings.entryDay(sheet) : LocalDate.parse(date);
658	        } catch (DateTimeParseException e) {
659	            throw new InvalidClaimException("Line " + at + ": not a valid date: " + date);
660	        }
661	        if (periods.closedOn(sheet, person.dueBy(sheet, on, settings, holidays))) {
662	            throw new InvalidClaimException("Line " + at + ": a claim may not be due inside a closed period");
663	        }
664	        if (person.retiredBefore(on)) {
665	            throw new InvalidClaimException(
666	                    "Line " + at + ": a claim may not be dated after the person's retirement date");
667	        }
668	        return new PastedClaim(person, new ClaimInput(value, on, note));
669	    }
