  const [inlineAmount, setInlineAmount] = useState('');
  const inlineMutation = useMutation({
    mutationFn: (amount: string) =>
      putJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}`, user), {
        amount,
        date: claim.date,
        note: claim.note,
        corrects: claim.corrects ?? '',
      }),
